// Returns each item's `n`, uppercased when `a == 1`; null/undefined items are skipped.
function proc(items) {
  return items
    .filter((item) => item != null)
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

// Splits a comma-separated string into trimmed, non-empty parts.
function f2(str) {
  return str
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean);
}

module.exports = { proc, f2 };

